import json,numpy as np
m=json.load(open('/app/output/runs/111_reach_open_fridge_mid_shelf/meta.json'))['cameras']['robot_r1:zed_link:Camera:0']
K=np.array(m['intrinsic_cv']); E=np.array(m['extrinsic_cv']); R=E[:,:3]; t=E[:,3]; C=-R.T@t; Rcw=R.T
print('camera',C)
for uv in [(115,135),(120,145),(150,145),(80,135),(50,130),(150,175),(120,110),(90,100)]:
 d=Rcw@np.linalg.inv(K)@np.array([*uv,1.]);
 for z in [0.85,0.65,1.0]:
  s=(z-C[2])/d[2]
  if s>0: print(uv,'z',z,'world',np.round(C+s*d,2))
